import { default as __ns1_approxEqual } from "./src/approx_equal.js";
import { default as __ns1_binomialDistribution } from "./src/binomial_distribution.js";
import { default as __ns1_epsilon } from "./src/epsilon.js";
import { default as __ns1_max } from "./src/max.js";
import { default as __ns1_sum } from "./src/sum.js";
const ss = Object.freeze({ approxEqual: __ns1_approxEqual, binomialDistribution: __ns1_binomialDistribution, epsilon: __ns1_epsilon, max: __ns1_max, sum: __ns1_sum });
{
